struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* createList(int n, int arr[]) {
    if (n == 0) return nullptr;

    ListNode *head = new ListNode(arr[0]);
    ListNode *current = head;

    for (int i = 1; i < n; i++) {
        current->next = new ListNode(arr[i]);
        current = current->next;
    }

    return head;
}

void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->val;
        if (current->next != nullptr) {
            cout << " ";
        }
        current = current->next;
    }
    cout << endl;
}

ListNode* removeElements(ListNode* head, int val) {
    ListNode *dummy = new ListNode(0);
    dummy->next = head;
    ListNode *prev = dummy;
    ListNode *current = head;

    while (current != nullptr) {
        if (current->val == val) {
            prev->next = current->next;
            delete current;
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }

    ListNode *newHead = dummy->next;
    delete dummy;
    return newHead;
}

int main() {
    int n;
    cin >> n;

    int *arr = new int[n];
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    int val;
    cin >> val;

    ListNode *head = createList(n, arr);
    head = removeElements(head, val);
    printList(head);

    // 释放内存
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }

    delete[] arr;
    return 0;
}

