#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

struct Node {
    char ch;
    int freq;
    int left, right;
    Node(char c, int f) : ch(c), freq(f), left(-1), right(-1) {}
};

bool operator<(const Node& a, const Node& b) {
    return a.freq > b.freq;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<Node> nodes(n);
    for (int i = 0; i < n; ++i) {
        int freq;
        char ch;
        std::cin >> freq >> ch;
        nodes[i] = Node(ch, freq);
    }

    std::priority_queue<Node> pq(nodes.begin(), nodes.end());

    while (pq.size() > 1) {
        Node left = pq.top();
        pq.pop();
        Node right = pq.top();
        pq.pop();

        Node parent(left.ch, left.freq + right.freq);
        parent.left = left.ch;
        parent.right = right.ch;
        pq.push(parent);
    }

    for (int i = 0; i < n; ++i) {
        std::cout << nodes[i].ch << " " << nodes[i].freq << " " << nodes[i].left << " " << nodes[i].right << std::endl;
    }

    return 0;
}

