struct Node {
    int number;
    Node* next;
    Node(int num) : number(num), next(nullptr) {}
};

int josephus(int n, int m) {
    if (n == 1) return 1;

    // 创建循环单链表
    Node* head = new Node(1);
    Node* current = head;
    for (int i = 2; i <= n; ++i) {
        current->next = new Node(i);
        current = current->next;
    }
    current->next = head; // 形成循环

    Node* prev = current;
    current = head;

    // 开始模拟报数过程
    while (current->next != current) {
        // 报数到m-1，因为当前节点算作1
        for (int i = 1; i < m; ++i) {
            prev = current;
            current = current->next;
        }

        // 删除当前节点
        prev->next = current->next;
        Node* toDelete = current;
        current = current->next;
        delete toDelete;
    }

    int result = current->number;
    delete current;
    return result;
}

int main() {
    int n, m;
    cin >> n >> m;
    cout << josephus(n, m) << endl;
    return 0;
}

