struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

bool isValidBST(TreeNode* root, long long min_val, long long max_val) {
    if (root == NULL) return true;

    if (root->val <= min_val || root->val >= max_val) {
        return false;
    }

    return isValidBST(root->left, min_val, root->val) && 
           isValidBST(root->right, root->val, max_val);
}

TreeNode* buildTree(const vector<int>& levelOrder) {
    if (levelOrder.empty() || levelOrder[0] == 0) return NULL;

    TreeNode* root = new TreeNode(levelOrder[0]);
    vector<TreeNode*> nodes;
    nodes.push_back(root);

    int i = 1;
    while (i < levelOrder.size()) {
        TreeNode* current = nodes.front();
        nodes.erase(nodes.begin());

        if (i < levelOrder.size() && levelOrder[i] != 0) {
            current->left = new TreeNode(levelOrder[i]);
            nodes.push_back(current->left);
        }
        i++;

        if (i < levelOrder.size() && levelOrder[i] != 0) {
            current->right = new TreeNode(levelOrder[i]);
            nodes.push_back(current->right);
        }
        i++;
    }

    return root;
}

